import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;
import java.util.stream.Collectors;

class Solution {
    public static HashMap<Integer, Integer> countFrequencies(List<Integer> arr) {
        HashMap<Integer, Integer> freq = new HashMap<>();
        for (int num : arr) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }
        return freq;
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> arr = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        Map<Integer, Integer> res = countFrequencies(arr);
        Map<Integer, Integer> resSorted = new TreeMap<>(res);
        for (int key : resSorted.keySet()) {
            System.out.println(key + " " + resSorted.get(key));
        }
    }
}
